import { observer } from 'mobx-react-lite';
import React, { useEffect, useState } from 'react';
import { useContext } from 'react';
import { Context } from '../index';
import { getBasket , delFromBasket, cleanBasket } from '../http/basketAPI';
import { Button, Card, Col, Container, Row } from 'react-bootstrap'
import { createOrder } from '../http/orderAPI';
import CreateOrder from '../components/modals/CreateOrder';

const Basket = observer(() => {
  const {dish} = useContext(Context)

  const [orderVisible, setOrderVisible] = useState(false)

    useEffect(() => {
        getBasket().then(data => dish.setBaskets(data))
    }, [])

    let prices = 0;

    {dish.basket.map(price =>
        prices += Number(price.dish.price)
    )}

    const clean = () => {
      cleanBasket()
      window.location.reload()
    }
    const del = (id) => {
      delFromBasket(id)
      window.location.reload()
    }

  return (
    <Container
      className="d-flex flex-sm-column justify-content-center align-items-center mt-3"
    >
      <h1 className="pb-2">Кошик</h1>

      {prices === 0 ?
        []
        :
        <Button variant='outline-danger' onClick={()=> clean()}>Очистити кошик</Button>
      }
      <hr/>
      {dish.basket.map(product =>
                <Card className="d-flex w-100 p-2 justify-content-center mb-2" key={product.id}>
                    <Row className="d-flex w-100">
                        <Col>
                            <div className="d-flex flex-row align-items-center">
                                <img className='rounded-2' src={process.env.REACT_APP_API_URL + product.dish.img} width={50} />
                                <h3 className="pl-3">{product.dish.name}</h3>
                            </div>
                        </Col>
                        <Col>
                            <div className="d-flex h-100 flex-row justify-content-end align-items-center">
                                <Button
                                  variant="outline-danger"
                                  onClick={()=> del(product.id)}
                                >
                                  Видалити
                                </Button>
                                <h3 className="font-weight-light">{product.dish.price} грн</h3>
                            </div>
                        </Col>
                    </Row>

                </Card>
        )}
        <hr/>
        <Card className="d-flex flex-row  p-2 ml-auto mb-2">
          <h3 className="pr-2">Усього: </h3>
          <h3 className="pl-2"> {prices}<span className="font-weight-light pl-2"> грн</span></h3>
        </Card>
        {prices === 0 ?
        []
        :
        <Button onClick={() => setOrderVisible(true)}>Створити замовлення</Button>
        }
        <CreateOrder show={orderVisible} onHide={() => setOrderVisible(false)}/>
    </Container>
  );
});

export default Basket;
